// The bits hi..lo of the encoding
#define BITS(hi, lo) (((e) >> (lo)) & ((1u << ((hi) - (lo) + 1)) - 1))
// An operand spec: the kind, the position of the field, the flags, the extra
#define S(kind, position, flags, extra) { kind, position, flags, extra }
// An entry: the mnemonic, the mask and the value, the feature, the flags, the
// flow, the condition and the operands
#define E(mnemonic, mask, value, feature, flags, flow, condition, ...) \
    { mnemonic, mask, value, { __VA_ARGS__ }, ArmFeatures::feature, flags, flow, condition }
// The common flows
#define FLOW_JUMP (Opcode::FLOW_COND_ALWAYS | Opcode::FLOW_RELATIVE_JMP)
#define FLOW_CALL (Opcode::FLOW_STACK_CHANGE | Opcode::FLOW_COND_ALWAYS | Opcode::FLOW_RELATIVE_JMP)
#define FLOW_COND (Opcode::FLOW_COND_ZERO | Opcode::FLOW_RELATIVE_JMP)
#define FLOW_JUMP_REGISTER (Opcode::FLOW_COND_ALWAYS | Opcode::FLOW_ACTION)
#define FLOW_CALL_REGISTER (Opcode::FLOW_STACK_CHANGE | Opcode::FLOW_COND_ALWAYS | Opcode::FLOW_ACTION)
#define FLOW_RETURN (Opcode::FLOW_RET | Opcode::FLOW_ACTION)
#define FLOW_TRAP (Opcode::FLOW_DEBUG)

// True if the sys alias of 'scheme' names the operation of the instruction and
// takes (or not) a register
bool isNamedOption(uint32 e, uint scheme, bool takesRegister)
{
    uint value = BITS(18, 5);
    return (getOptionName(scheme, value) != NULL) &&
           (optionTakesRegister(scheme, value) == takesRegister);
}

// True if 'value' (of a register of 'size' bits) is a movz of one 16 bit chunk
bool isMovzValue(uint64 value, uint size)
{
    if (size == 32)
        value &= 0xFFFFFFFFu;
    for (uint shift = 0; shift < size; shift += 16)
        if ((value & ~((uint64)0xffff << shift)) == 0)
            return true;
    return false;
}

// True if 'value' is built by a movz or a movn
bool isMoveWideValue(uint64 value, uint size)
{
    uint64 inverted = ~value;
    if (size == 32)
        inverted &= 0xFFFFFFFFu;
    return isMovzValue(value, size) || isMovzValue(inverted, size);
}

// The mov alias of an orr (bitmask immediate): the value is not a move wide
bool isLogicalMoveAlias(uint32 e, uint size)
{
    uint64 value;
    if (!decodeLogicalImmediateValue(BITS(22, 22), BITS(21, 16), BITS(15, 10), size, value))
        return false;
    return !isMoveWideValue(value, size);
}

// The mov alias of a movn: the value is not a movz (lsl #0 takes precedence)
bool isMoveNegatedAlias(uint32 e, uint size)
{
    uint hw = BITS(22, 21);
    uint64 imm16 = BITS(20, 5);
    if ((imm16 == 0) && (hw != 0))
        return false;
    uint64 value = ~(imm16 << (hw * 16));
    if (size == 32)
        value &= 0xFFFFFFFFu;
    return !isMovzValue(value, size);
}


bool condition0(uint32 e)
{
    return BITS(4, 0) == 31 || BITS(9, 5) == 31;
}

bool condition1(uint32 e)
{
    return isLogicalMoveAlias(e, 32);
}

bool condition2(uint32 e)
{
    return isLogicalMoveAlias(e, 64);
}

bool condition3(uint32 e)
{
    return BITS(20, 5) != 0 || BITS(21, 21) == 0;
}

bool condition4(uint32 e)
{
    return isMoveNegatedAlias(e, 32);
}

bool condition5(uint32 e)
{
    return BITS(20, 5) != 0 || BITS(22, 21) == 0;
}

bool condition6(uint32 e)
{
    return isMoveNegatedAlias(e, 64);
}

bool condition7(uint32 e)
{
    return BITS(14, 10) < BITS(20, 16);
}

bool condition8(uint32 e)
{
    return BITS(14, 10) >= BITS(20, 16);
}

bool condition9(uint32 e)
{
    return BITS(14, 10) != 31 && BITS(14, 10) + 1 == BITS(20, 16);
}

bool condition10(uint32 e)
{
    return BITS(15, 10) < BITS(21, 16);
}

bool condition11(uint32 e)
{
    return BITS(15, 10) >= BITS(21, 16);
}

bool condition12(uint32 e)
{
    return BITS(15, 10) != 63 && BITS(15, 10) + 1 == BITS(21, 16);
}

bool condition13(uint32 e)
{
    return BITS(9, 5) == BITS(20, 16);
}

bool condition14(uint32 e)
{
    return (BITS(15, 12) >> 1) != 7;
}

bool condition15(uint32 e)
{
    return (BITS(15, 12) >> 1) != 7 && BITS(9, 5) == BITS(20, 16) && BITS(9, 5) != 31;
}

bool condition16(uint32 e)
{
    return (BITS(15, 12) >> 1) != 7 && BITS(9, 5) == BITS(20, 16);
}

bool condition17(uint32 e)
{
    return getOptionName(ARM_OPT_BARRIER, BITS(11, 8)) != NULL;
}

bool condition18(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_DC, true);
}

bool condition19(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_DC, false);
}

bool condition20(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_IC, true);
}

bool condition21(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_IC, false);
}

bool condition22(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_AT, true);
}

bool condition23(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_AT, false);
}

bool condition24(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_TLBI, true);
}

bool condition25(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_TLBI, false);
}

bool condition26(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_PLBI, true);
}

bool condition27(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_PLBI, false);
}

bool condition28(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_BRB, true) || isNamedOption(e, ARM_OPT_SYS_BRB, false);
}

bool condition29(uint32 e)
{
    return isNamedOption(e, ARM_OPT_SYS_TLBIP, true);
}

bool condition30(uint32 e)
{
    return BITS(4, 0) != 31 && BITS(20, 16) != 31;
}

bool condition31(uint32 e)
{
    return BITS(4, 0) != BITS(9, 5) && BITS(4, 0) != BITS(20, 16) && BITS(9, 5) != BITS(20, 16) && BITS(4, 0) != 31 && BITS(20, 16) != 31;
}

bool condition32(uint32 e)
{
    return BITS(4, 0) != BITS(9, 5) && BITS(4, 0) != BITS(20, 16) && BITS(9, 5) != BITS(20, 16) && BITS(4, 0) != 31;
}

bool condition33(uint32 e)
{
    return (BITS(4, 0) & 1) == 0 && BITS(4, 0) <= 22;
}


#undef BITS
